INSERT INTO laws (category, title, act_name, section_ref, summary, keywords) VALUES
('Family','Divorce (Talaq) procedure for Muslims','Muslim Family Laws Ordinance, 1961','Section 7','A husband who pronounces talaq must give written notice to the Chairman of the Union Parishad/City Corporation and send a copy to the wife. The Chairman forms an Arbitration Council to try reconciliation.','divorce talaq husband wife separation notice arbitration'),
('Family','Registration of marriage and dower (denmohor)','Muslim Marriages and Divorces (Registration) Act, 1974','','Muslim marriages must be registered by a licensed Nikah Registrar. The kabinnama records the dower amount and conditions agreed between the parties.','marriage nikah kabin denmohor dower registration'),
('Family','Maintenance and domestic violence protection','Domestic Violence (Prevention and Protection) Act, 2010','','Protects women and children from physical, psychological, sexual and economic abuse in the family. A victim can apply to the court for protection, residence and compensation orders.','domestic violence abuse wife beating maintenance protection harassment'),
('Family','Child custody and guardianship','Guardians and Wards Act, 1890','','The court decides guardianship and custody based on the welfare of the child.','custody child guardian guardianship children'),
('Criminal','Theft, cheating and criminal breach of trust','Penal Code, 1860','Sections 378-420','Defines theft, extortion, cheating and breach of trust as crimes, with punishment of imprisonment and/or fine.','theft stolen cheating fraud cheated breach trust money'),
('Criminal','Bail and arrest procedure','Code of Criminal Procedure, 1898','','Explains when police can arrest, how a person should be produced before a Magistrate, and how bail is applied for.','arrest bail police custody remand fir case lodge'),
('Criminal','Dishonoured cheque','Negotiable Instruments Act, 1881','Section 138','If a cheque is returned unpaid for insufficient funds, the payee may send a legal notice and file a case if payment is not made within the time allowed.','cheque check bounce dishonour dishonoured bank payment notice'),
('Property','Transfer, sale and gift of property','Transfer of Property Act, 1882','','Governs sale, mortgage, lease and gift of immovable property, and what documents and registration are required.','land property sale buy deed mortgage lease gift flat plot'),
('Property','Registration of documents','Registration Act, 1908','','Certain documents about land, such as sale deeds, must be registered at the Sub-Registry office to be valid.','registration deed land sub-registrar mutation document'),
('Property','Landlord and tenant (house rent)','Premises Rent Control Act, 1991','','Regulates rent, advance, and eviction of tenants from premises, with grounds a landlord must show to evict.','rent tenant landlord eviction house flat advance evict'),
('Labour','Wages, termination and working conditions','Bangladesh Labour Act, 2006','','Sets rules on wages, working hours, leave, termination, compensation and workplace safety for workers.','job salary wage terminated fired termination worker employee labour overtime leave factory'),
('Consumer','Defective goods and unfair trade','Consumer Rights Protection Act, 2009','','Protects consumers from selling above fixed price, adulteration, false advertising and defective goods. Complaints can be made to the Directorate of National Consumer Rights Protection.','consumer product defective fake expired price shop refund complaint'),
('Cyber','Online harassment and cyber crime','Cyber Security law of Bangladesh (check current Act/Ordinance)','','Online fraud, hacking, identity theft, and abusive or defamatory online content can be reported. Check the current law and the authority where complaints are filed.','facebook online internet hack hacked cyber harassment blackmail photo fake id social media'),
('Contract','Breach of contract and damages','Contract Act, 1872','','A valid contract needs offer, acceptance, lawful consideration and free consent. If a party breaks the contract, the other may claim compensation.','contract agreement breach broke promise damages business partner payment'),
('Contract','Recovering money owed','Code of Civil Procedure, 1908','','A person owed money may send a legal notice and file a money suit in the civil court within the limitation period.','loan money debt owed recover payment civil suit notice'),
('Inheritance','Inheritance / succession of property','Muslim Personal Law (Shariat) Application Act, 1937 / Succession Act, 1925','','Inheritance follows the personal law of the family (Muslim, Hindu, Christian, etc.) which sets each heir\'s share.','inheritance heir succession father death property share will wasiyat');
